PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX schema: <http://schema.org/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?date) AS ?frostDays)
WHERE {
  GRAPH <hydroturtle/lamah_ce> {
    ?obs a sosa:Observation ;
         sosa:madeBySensor ?station ;
         sosa:observedProperty hyobs:AirTemperature2mAvg ;
         sosa:resultTime ?date ;
         sosa:hasResult ?result .
    ?station schema:name "Bangs" .
    ?result qudt:numericValue ?temp .
    FILTER(?temp < 0)
    FILTER(?date >= "2010-01-01T00:00:00"^^xsd:dateTime && ?date < "2021-01-01T00:00:00"^^xsd:dateTime)
  }
}
